use std::fmt::Debug;
pub struct Safe;
impl Safe {
    #[inline(never)]
    pub fn unwrap(&self) -> u8 { 7 }
    #[inline(never)]
    pub fn expect(&self, _: &str) -> u8 { 8 }
}
#[inline(never)]
pub fn options(a: Option<u8>, b: Option<u8>) -> u8 {
    let x = a.unwrap(); let y = b.unwrap(); let z = a.unwrap();
    let w = b.expect("option"); x ^ y ^ z ^ w
}
#[inline(never)]
pub fn results(a: Result<u8, u8>, b: Result<u8, u8>) -> u8 {
    let x = a.unwrap(); let y = b.unwrap(); let z = a.expect("result a");
    let w = b.expect("result b"); x ^ y ^ z ^ w
}
#[inline(never)]
pub fn custom(s: Safe) -> u8 { s.unwrap() ^ s.expect("safe") }
#[inline(never)]
pub fn chain(x: Option<Option<u8>>) -> u8 { x.unwrap().expect("chain") }
#[inline(never)]
pub fn generic<T: Copy + Debug>(x: Option<T>) -> T { x.unwrap() }
#[inline(never)]
pub fn unicode(x: Option<u8>) -> u8 { let _ = "é🦀"; x.expect("unicode") }
macro_rules! produced { ($x:expr) => { $x.expect("macro") }; }
#[inline(never)]
pub fn expanded(x: Option<u8>) -> u8 { produced!(x) }
#[inline(never)]
pub fn indexing(xs: &[u8], i: usize) -> u8 { xs[i] }
#[inline(never)]
pub fn addition(x: u8) -> u8 { x + 1 }
#[inline(never)]
pub fn debug_control(x: u8) -> u8 { debug_assert!(x != 0); x }
#[cfg(feature = "extra")]
#[inline(never)]
pub fn feature_control(x: Option<u8>) -> u8 { x.expect("feature") }
#[cfg(not(feature = "extra"))]
#[inline(never)]
pub fn feature_control(_: Option<u8>) -> u8 { 9 }

