use panic_pilot::*;
fn main() {
    let mode = std::env::args().nth(1);
    match mode.as_deref() {
        Some("option") => { std::hint::black_box(options(None, Some(1))); }
        Some("result") => { std::hint::black_box(results(Err(2), Ok(1))); }
        Some("index") => { std::hint::black_box(indexing(&[1], 3)); }
        Some("overflow") => { std::hint::black_box(addition(std::hint::black_box(255))); }
        Some("debug") => { std::hint::black_box(debug_control(0)); }
        Some("feature") => { std::hint::black_box(feature_control(None)); }
        Some("macro") => { std::hint::black_box(expanded(None)); }
        Some("dependency") => { std::hint::black_box(pilot_dep::dependency(None)); }
        _ => {
            std::hint::black_box(options(Some(1), Some(2)));
            std::hint::black_box(results(Ok(1), Ok(2)));
            std::hint::black_box(custom(Safe));
            std::hint::black_box(chain(Some(Some(3))));
            std::hint::black_box(generic(Some(4u8)));
            std::hint::black_box(generic(Some(5u16)));
            std::hint::black_box(unicode(Some(6)));
            std::hint::black_box(expanded(Some(7)));
            std::hint::black_box(pilot_dep::dependency(Some(8)));
            std::hint::black_box(indexing(&[1], 0));
            std::hint::black_box(addition(1));
            std::hint::black_box(debug_control(1));
            std::hint::black_box(feature_control(Some(1)));
        }
    }
}
